import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=s=>document.querySelector(s), game=$('#game');
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x9dbdc3); scene.fog=new THREE.Fog(0x9dbdc3,38,115);
const camera=new THREE.PerspectiveCamera(72,innerWidth/innerHeight,.1,220); camera.rotation.order='YXZ';
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.7)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.05; game.appendChild(renderer.domElement);
const hemi=new THREE.HemisphereLight(0xd8eff0,0x443222,2.1); scene.add(hemi); const sun=new THREE.DirectionalLight(0xffe6bd,3.2); sun.position.set(-14,28,12); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); sun.shadow.camera.left=-38;sun.shadow.camera.right=38;sun.shadow.camera.top=38;sun.shadow.camera.bottom=-38; scene.add(sun);
const groundMat=new THREE.MeshStandardMaterial({color:0x755238,roughness:1}); const ground=new THREE.Mesh(new THREE.PlaneGeometry(240,240),groundMat); ground.rotation.x=-Math.PI/2;ground.position.y=-.06;ground.receiveShadow=true;scene.add(ground);
const grid=new THREE.GridHelper(120,120,0xd4b68c,0x9b7856);grid.position.y=-.045;grid.material.transparent=true;grid.material.opacity=.22;scene.add(grid);
// Distant low-poly ridges make the worksite feel like a place, not an empty plane.
const rand=(a,b)=>a+Math.random()*(b-a); for(let i=0;i<28;i++){const h=rand(5,14),r=rand(9,19),m=new THREE.Mesh(new THREE.ConeGeometry(r,h,5),new THREE.MeshStandardMaterial({color:new THREE.Color().setHSL(rand(.07,.12),rand(.18,.34),rand(.25,.4)),roughness:1}));m.position.set(rand(-100,100),h/2-1,rand(-100,100));m.rotation.y=rand(0,6);m.receiveShadow=true;scene.add(m)}
const player={pos:new THREE.Vector3(0,1.72,7),yaw:0,pitch:0,velocity:new THREE.Vector3(),grounded:true};camera.position.copy(player.pos);
let objects=[], selected='dirt', activeTab='build', panelOpen=true, locked=false, dayTime=12, last=performance.now(), worldName='UNTITLED';
const objectTypes=[{id:'dirt',name:'Dirt block',icon:'🟫',color:'#9b6946',shape:'box'},{id:'grass',name:'Grass block',icon:'🟩',color:'#78a45b',shape:'box'},{id:'stone',name:'Stone block',icon:'⬜',color:'#92968f',shape:'box'},{id:'wood',name:'Wood post',icon:'🪵',color:'#a66e42',shape:'post'},{id:'lamp',name:'Glow orb',icon:'💡',color:'#ffd879',shape:'orb'},{id:'tree',name:'Tiny tree',icon:'🌳',color:'#558752',shape:'tree'},{id:'water',name:'Water',icon:'🟦',color:'#40a9be',shape:'water'},{id:'crate',name:'Crate',icon:'📦',color:'#c48b51',shape:'crate'},{id:'custom',name:'Custom',icon:'✨',color:'#c8f05b',shape:'box'}];
let customConfigs=[];
function makeMaterial(color,emissive=0){return new THREE.MeshStandardMaterial({color,roughness:.82,metalness:.02,emissive:emissive?new THREE.Color(color):0,emissiveIntensity:emissive})}
function addMesh(type,position,config={}){const data=objectTypes.find(x=>x.id===type)||objectTypes.at(-1), color=config.color||data.color, size=config.size||1;let group=new THREE.Group();group.position.copy(position);group.userData={type,name:config.name||data.name,color,size};
 const box=(x,y,z,mat)=>{let o=new THREE.Mesh(new THREE.BoxGeometry(x,y,z),mat);o.castShadow=true;o.receiveShadow=true;group.add(o);return o};
 if(data.shape==='box'){const b=box(size,size,size,makeMaterial(color));b.position.y=size/2}
 else if(data.shape==='post'){const b=box(.6*size,2*size,.6*size,makeMaterial(color));b.position.y=size;}
 else if(data.shape==='orb'){const orb=new THREE.Mesh(new THREE.SphereGeometry(.55*size,20,14),makeMaterial(color,.8));orb.position.y=.6*size;orb.castShadow=true;group.add(orb);const glow=new THREE.PointLight(color,2.4,8);glow.position.y=.7*size;group.add(glow)}
 else if(data.shape==='tree'){let trunk=box(.28*size,1.1*size,.28*size,makeMaterial('#795033'));trunk.position.y=.55*size;const leaves=new THREE.Mesh(new THREE.IcosahedronGeometry(.8*size,1),makeMaterial(color));leaves.position.y=1.55*size;leaves.castShadow=true;group.add(leaves)}
 else if(data.shape==='water'){const w=new THREE.Mesh(new THREE.BoxGeometry(size,.18*size,size),new THREE.MeshPhysicalMaterial({color,transparent:true,opacity:.77,roughness:.18,metalness:.08}));w.position.y=.09*size;w.receiveShadow=true;group.add(w)}
 else if(data.shape==='crate'){const b=box(size,size,size,makeMaterial(color));b.position.y=size/2;const edge=new THREE.EdgesGeometry(new THREE.BoxGeometry(size*1.005,size*1.005,size*1.005));const lines=new THREE.LineSegments(edge,new THREE.LineBasicMaterial({color:'#563b28'}));lines.position.y=size/2;group.add(lines)}
 group.traverse(o=>{if(o.isMesh){o.userData.owner=group}});scene.add(group);objects.push(group);updateCount();return group;
}
function updateCount(){$('#objectCount').textContent=objects.length}
function clearObjects(){objects.forEach(o=>scene.remove(o));objects=[];updateCount()}
// Starter scene: a small dirt patch and a friendly sample build.
for(let x=-3;x<=3;x++)for(let z=-2;z<=2;z++)if(Math.random()>.13)addMesh(Math.random()>.7?'grass':'dirt',new THREE.Vector3(x,0,z),{size:1});
addMesh('tree',new THREE.Vector3(-4,0,-2));addMesh('lamp',new THREE.Vector3(3,0,-1));addMesh('crate',new THREE.Vector3(2,0,2));
const raycaster=new THREE.Raycaster();raycaster.far=9;const pointer=new THREE.Vector2(0,0);let hitTarget=null;
function targetHit(){raycaster.setFromCamera(pointer,camera);const candidates=[];objects.forEach(o=>o.traverse(c=>{if(c.isMesh)candidates.push(c)}));return raycaster.intersectObjects(candidates,false)[0]||null}
function forward(){return new THREE.Vector3(-Math.sin(player.yaw),0,-Math.cos(player.yaw))}
function placeSelected(){const h=targetHit();let pos;if(h&&h.object.userData.owner){const obj=h.object.userData.owner;const normal=h.face? h.face.normal.clone().transformDirection(h.object.matrixWorld):new THREE.Vector3(0,1,0);pos=h.point.clone().addScaledVector(normal,.52);pos.x=Math.round(pos.x);pos.y=Math.max(0,Math.round(pos.y));pos.z=Math.round(pos.z)}else{pos=player.pos.clone().addScaledVector(forward(),3);pos.y=0;pos.x=Math.round(pos.x);pos.z=Math.round(pos.z)}const c=customConfigs.find(c=>c.id===selected);addMesh(selected,pos,c||{});toast('Placed '+(c?.name||objectTypes.find(o=>o.id===selected)?.name||'object'))}
function removeTarget(){const h=targetHit();if(h?.object.userData.owner){const o=h.object.userData.owner;scene.remove(o);objects=objects.filter(a=>a!==o);updateCount();toast('Object removed')}}
renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());renderer.domElement.addEventListener('mousedown',e=>{if(!locked){if(e.button===0)renderer.domElement.requestPointerLock();return}if(e.button===0)removeTarget();if(e.button===2)placeSelected()});document.addEventListener('pointerlockchange',()=>{locked=document.pointerLockElement===renderer.domElement;$('#welcome').classList.toggle('hidden',locked);});document.addEventListener('mousemove',e=>{if(!locked)return;player.yaw-=e.movementX*.0022;player.pitch-=e.movementY*.0022;player.pitch=Math.max(-1.48,Math.min(1.48,player.pitch))});
const keys={};document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.code==='KeyF')togglePanel();if(e.code==='Escape'&&locked){document.exitPointerLock();$('#welcome').classList.remove('hidden')}if(/^Digit[1-8]$/.test(e.code))selectItem(objectTypes[(+e.code.slice(5)-1)%objectTypes.length].id)});document.addEventListener('keyup',e=>keys[e.code]=false);

