document.addEventListener('keyup',e=>keys[e.code]=false);
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),1800)}
function togglePanel(force){panelOpen=typeof force==='boolean'?force:!panelOpen;$('#admin').classList.toggle('closed',!panelOpen);$('#adminToggle').style.display=panelOpen?'none':'block'}
$('#closeAdmin').onclick=()=>togglePanel(false);$('#adminToggle').onclick=()=>togglePanel(true);
function selectItem(id){selected=id;const d=customConfigs.find(c=>c.id===id)||objectTypes.find(o=>o.id===id);$('#toolLabel').textContent=d?.name||id;renderHotbar();renderPanel()}
function renderHotbar(){const list=[...objectTypes.slice(0,8)];$('#hotbar').innerHTML=list.map((it,i)=>`<button class="slot ${selected===it.id?'active':''}" data-id="${it.id}"><small>${i+1}</small>${it.icon}<em>${it.name.split(' ')[0]}</em></button>`).join('');$('#hotbar').querySelectorAll('.slot').forEach(b=>b.onclick=()=>selectItem(b.dataset.id))}
function setTab(tab){activeTab=tab;document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));renderPanel()}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));
function renderPanel(){const root=$('#panelContent');if(activeTab==='build'){const choices=[...objectTypes.slice(0,8),...customConfigs];root.innerHTML=`<div class="section"><div class="section-title">Object library <small>${choices.length} available</small></div><div class="items">${choices.map(o=>`<button class="item ${selected===o.id?'selected':''}" data-id="${o.id}"><i class="dot" style="background:${o.color}"></i><div class="emoji">${o.icon||'✨'}</div><span>${o.name}</span></button>`).join('')}</div></div><div class="section"><div class="section-title">Quick actions</div><div class="btn-row"><button class="btn" id="spawnBtn">＋ Spawn in front</button><button class="btn secondary" id="removeBtn">⌫ Remove target</button></div></div><div class="section"><div class="section-title">Creator tip</div><div style="font-size:10px;line-height:1.55;color:#9da69b">Right-click to place at your crosshair. Left-click to erase. Add custom object configurations in the Configs tab — no limits.</div></div>`;root.querySelectorAll('.item').forEach(b=>b.onclick=()=>selectItem(b.dataset.id));$('#spawnBtn').onclick=()=>placeSelected();$('#removeBtn').onclick=()=>removeTarget()}else if(activeTab==='world'){root.innerHTML=`<div class="section"><div class="section-title">World settings <small>live controls</small></div><div class="field"><label>World name</label><input id="worldName" type="text" value="${worldName}" placeholder="My dirt world"></div><div class="field"><label>Walk speed <output id="speedOut">5.0</output></label><input id="speed" type="range" min="2" max="14" step=".5" value="5"></div><div class="field"><label>Gravity <output id="gravOut">18</output></label><input id="gravity" type="range" min="4" max="32" step="1" value="18"></div><div class="field"><label>Time of day <output id="dayOut">12:00</output></label><input id="day" type="range" min="0" max="24" step=".1" value="12"></div><div class="field"><label>Lighting mood</label><select id="mood"><option value="natural">Natural</option><option value="sunset">Warm sunset</option><option value="night">Midnight</option><option value="dream">Dreamy pastel</option></select></div></div><div class="section"><div class="section-title">World tools</div><div class="btn-row"><button class="btn secondary" id="terrainBtn">＋ Dirt patch</button><button class="btn secondary" id="clearBtn">Clear objects</button></div></div><div class="section"><div class="section-title">Save data</div><div class="btn-row"><button class="btn" id="saveWorld">Save world</button><button class="btn secondary" id="loadWorld">Load saved</button></div></div>`;
